class Graph:
    def __init__(self):
        self.nodes = {}

    def create_node(self, node_id):
        if node_id not in self.nodes:
            self.nodes[node_id] = set()
            return f"node {node_id} created"
        else:
            return f"node {node_id} already exists"

    def add_edge(self, node1, node2):
        if node1 not in self.nodes or node2 not in self.nodes:
            return "One or both of the nodes do not exist"

        self.nodes[node1].add(node2)
        return f"{node1} has an edge to {node2}"

# Example usage:
g = Graph()
print(g.create_node(1))  # Output: node 1 created
print(g.create_node(2))  # Output: node 2 created
print(g.add_edge(1, 2))  # Output: node 1 has an edge to 2
```

This function allows you to create nodes and add edges between them. The `create_node` function checks if a node already exists before creating it, and the `add_edge` function checks if both nodes exist before adding the edge.
